mapper.delete:
DELETE FROM MATCH_QUEUE
WHERE MEMBER_SEQ = #{memberSeq}
AND MATCH_TYPE = 'IDEAL'

mapper.select:
WITH cfg AS ( SELECT NVL(MAX(CASE CONFIG_KEY WHEN 'IDEAL_MIN_SCORE' THEN TO_NUMBER(CONFIG_VALUE) END), 70) AS MIN_SCORE, NVL(MAX(CASE CONFIG_KEY WHEN 'W_SMOKING' THEN TO_NUMBER(CONFIG_VALUE) END), 3) AS W_SMOKING, NVL(MAX(CASE CONFIG_KEY WHEN 'W_DRINKING' THEN TO_NUMBER(CONFIG_VALUE) END), 2) AS W_DRINKING, NVL(MAX(CASE CONFIG_KEY WHEN 'W_HEIGHT' THEN TO_NUMBER(CONFIG_VALUE) END), 2) AS W_HEIGHT, NVL(MAX(CASE CONFIG_KEY WHEN 'W_MBTI' THEN TO_NUMBER(CONFIG_VALUE) END), 1) AS W_MBTI, NVL(MAX(CASE CONFIG_KEY WHEN 'W_MILITARY' THEN TO_NUMBER(CONFIG_VALUE) END), 2) AS W_MILITARY, NVL(MAX(CASE CONFIG_KEY WHEN 'W_BODY' THEN TO_NUMBER(CONFIG_VALUE) END), 2) AS W_BODY, NVL(MAX(CASE CONFIG_KEY WHEN 'IDEAL_MIN_SCORE_FLOOR' THEN TO_NUMBER(CONFIG_VALUE) END), 40) AS FLOOR_SCORE, NVL(MAX(CASE CONFIG_KEY WHEN 'IDEAL_RELAX_STEP' THEN TO_NUMBER(CONFIG_VALUE) END), 10) AS RELAX_STEP, NVL(MAX(CASE CONFIG_KEY WHEN 'IDEAL_RELAX_SEC' THEN TO_NUMBER(CONFIG_VALUE) END), 30) AS RELAX_SEC FROM SYS_MATCHING_CONFIG ), th AS ( /* 이번 탐색의 기준점 (기본값: 0초 70 → 30초 60 → 60초 50 → 90초~ 40) */ SELECT LEAST(MIN_SCORE, GREATEST(FLOOR_SCORE, MIN_SCORE - RELAX_STEP * FLOOR(#{waitedSec} / NULLIF(RELAX_SEC, 0)))) AS MIN_SCORE FROM cfg ), me AS ( SELECT m.MEMBER_SEQ, m.GENDER, TRUNC(MONTHS_BETWEEN(SYSDATE, m.BIRTH_DATE) / 12) AS AGE, it.AGE_MIN, it.AGE_MAX FROM MEMBER m LEFT JOIN IDEAL_TYPE it ON it.LOGIN_ID = m.LOGIN_ID WHERE m.MEMBER_SEQ = #{memberSeq} ), cand AS ( SELECT q.MEMBER_SEQ FROM MATCH_QUEUE q JOIN MEMBER m ON m.MEMBER_SEQ = q.MEMBER_SEQ JOIN MEMBER_PROFILE p ON p.MEMBER_SEQ = q.MEMBER_SEQ LEFT JOIN IDEAL_TYPE it ON it.LOGIN_ID = m.LOGIN_ID CROSS JOIN me WHERE q.MATCH_TYPE = 'IDEAL' AND q.STATUS = 'WAITING' AND q.MEMBER_SEQ <> me.MEMBER_SEQ AND m.MEMBER_STATUS = 'ACTIVE' AND m.GENDER <> me.GENDER /* 상대 나이가 내 이상형 범위 안 */ AND TRUNC(MONTHS_BETWEEN(SYSDATE, m.BIRTH_DATE) / 12) BETWEEN NVL(me.AGE_MIN, 0) AND NVL(me.AGE_MAX, 200) /* 내 나이가 상대 이상형 범위 안 */ AND me.AGE BETWEEN NVL(it.AGE_MIN, 0) AND NVL(it.AGE_MAX, 200) AND NOT EXISTS ( SELECT 1 FROM MEMBER_BLOCK b WHERE (b.MEMBER_SEQ = me.MEMBER_SEQ AND b.BLOCKED_MEMBER_SEQ = q.MEMBER_SEQ) OR (b.MEMBER_SEQ = q.MEMBER_SEQ AND b.BLOCKED_MEMBER_SEQ = me.MEMBER_SEQ)) AND NOT EXISTS ( SELECT 1 FROM IDEAL_MATCHING im WHERE ((im.MEMBER_SEQ_1 = me.MEMBER_SEQ AND im.MEMBER_SEQ_2 = q.MEMBER_SEQ) OR (im.MEMBER_SEQ_1 = q.MEMBER_SEQ AND im.MEMBER_SEQ_2 = me.MEMBER_SEQ)) AND im.MATCHED_AT > SYSTIMESTAMP - INTERVAL '7' DAY) ), dir AS ( SELECT #{memberSeq} AS FROM_SEQ, MEMBER_SEQ AS TO_SEQ FROM cand UNION ALL SELECT MEMBER_SEQ, #{memberSeq} FROM cand ), item AS ( /* A_* : 이 항목을 점수에 반영하는지(가중치, 상관없음이면 0) */ /* H_* : 상대 프로필이 조건에 맞는지(1/0) */ SELECT d.FROM_SEQ, d.TO_SEQ, CASE WHEN it.MIN_HEIGHT IS NOT NULL OR it.MAX_HEIGHT IS NOT NULL THEN c.W_HEIGHT ELSE 0 END AS A_HEIGHT, CASE WHEN tp.HEIGHT BETWEEN NVL(it.MIN_HEIGHT, 0) AND NVL(it.MAX_HEIGHT, 300) THEN 1 ELSE 0 END AS H_HEIGHT,
CASE WHEN it.MBTI_PREF IS NOT NULL THEN c.W_MBTI ELSE 0 END AS A_MBTI, /* 목록은 'ENFP, INTJ' 처럼 쉼표+공백으로 저장됨 → 공백 제거 후 비교 */ CASE WHEN INSTR(',' || REPLACE(it.MBTI_PREF, ' ') || ',', ',' || tp.MBTI || ',') > 0 THEN 1 ELSE 0 END AS H_MBTI,
/* 흡연: '비흡연자만' 일 때만 반영 */ CASE WHEN it.SMOKING_PREF = '비흡연자만' THEN c.W_SMOKING ELSE 0 END AS A_SMOKING, CASE WHEN tp.SMOKING = '비흡연' THEN 1 ELSE 0 END AS H_SMOKING,
/* 음주: 이상형 선택지 ↔ 프로필 선택지 매핑 */ CASE WHEN it.DRINKING_PREF IS NOT NULL AND it.DRINKING_PREF <> '상관없음' THEN c.W_DRINKING ELSE 0 END AS A_DRINKING, CASE WHEN it.DRINKING_PREF = '안 마시는 분' AND tp.DRINKING = '안 마셔요' THEN 1 WHEN it.DRINKING_PREF = '가끔 마시는 분' AND tp.DRINKING = '가끔' THEN 1 WHEN it.DRINKING_PREF = '잘 마시는 분' AND tp.DRINKING = '자주' THEN 1 ELSE 0 END AS H_DRINKING,
/* 병역: 이상형(여성 선택, 여러 개) ↔ 프로필(남성 입력). '상관없음'이 있으면 반영 안 함 */ CASE WHEN it.MILITARY_PREF IS NOT NULL AND INSTR(',' || REPLACE(it.MILITARY_PREF, ' ') || ',', ',상관없음,') = 0 THEN c.W_MILITARY ELSE 0 END AS A_MILITARY, CASE WHEN INSTR(',' || REPLACE(it.MILITARY_PREF, ' ') || ',', ',' || REPLACE(tp.MILITARY_STATUS, ' ') || ',') > 0 THEN 1 ELSE 0 END AS H_MILITARY,
/* 체형: 이상형(여러 개, 'A, B') ↔ 프로필(1개). 상대가 체형을 입력하지 않았으면 반영 안 함 */ CASE WHEN it.BODY_TYPE IS NOT NULL AND tp.BODY_TYPE IS NOT NULL THEN c.W_BODY ELSE 0 END AS A_BODY, CASE WHEN INSTR(',' || REPLACE(it.BODY_TYPE, ' ') || ',', ',' || REPLACE(tp.BODY_TYPE, ' ') || ',') > 0 THEN 1 ELSE 0 END AS H_BODY FROM dir d JOIN MEMBER fm ON fm.MEMBER_SEQ = d.FROM_SEQ LEFT JOIN IDEAL_TYPE it ON it.LOGIN_ID = fm.LOGIN_ID JOIN MEMBER_PROFILE tp ON tp.MEMBER_SEQ = d.TO_SEQ CROSS JOIN cfg c ), dir_score AS ( /* 반영할 항목이 하나도 없으면(전부 상관없음) 100점 */ SELECT FROM_SEQ, TO_SEQ, NVL( (A_HEIGHT*H_HEIGHT + A_MBTI*H_MBTI + A_SMOKING*H_SMOKING + A_DRINKING*H_DRINKING + A_MILITARY*H_MILITARY + A_BODY*H_BODY) / NULLIF(A_HEIGHT + A_MBTI + A_SMOKING + A_DRINKING + A_MILITARY + A_BODY, 0) * 100 , 100) AS SCORE FROM item ) SELECT * FROM ( SELECT ab.TO_SEQ AS CANDIDATE_SEQ, ROUND(ab.SCORE, 2) AS SCORE_ME_TO_CAND, ROUND(ba.SCORE, 2) AS SCORE_CAND_TO_ME, ROUND(SQRT(ab.SCORE * ba.SCORE), 2) AS MUTUAL_SCORE FROM dir_score ab JOIN dir_score ba ON ba.FROM_SEQ = ab.TO_SEQ AND ba.TO_SEQ = ab.FROM_SEQ CROSS JOIN th WHERE ab.FROM_SEQ = #{memberSeq} AND SQRT(ab.SCORE * ba.SCORE) >= th.MIN_SCORE /* 기준점이 낮아져도 점수 높은 후보가 먼저, 같은 점수면 랜덤 */ ORDER BY MUTUAL_SCORE DESC, DBMS_RANDOM.VALUE ) WHERE ROWNUM = 1
